type Token = { point: number; owner: string };
// A shared immutable membership snapshot sorts points and resolves ties deterministically.
function successor(tokens: readonly Token[], point: number): string {
  if (tokens.length === 0) throw new Error("NO_OWNER");
  let lo = 0, hi = tokens.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (tokens[mid].point < point) lo = mid + 1;
    else hi = mid;
  }
  return tokens[lo === tokens.length ? 0 : lo].owner;
}
